const solutionList = document.querySelector(".solutions__cards-list");

if (solutionList) {
  solutionList.addEventListener("click", (e) => {
    if (e.target.classList.contains("solutions__card-show")) {
      const openSolution = () => {
        const solution = e.target.closest(".solutions__card-bottom");
        const closeButton = solution.querySelector(
          ".solutions__card-content-close"
        );

        if (window.innerWidth > 1000) {
          moveCardList(solutionList, solution);
        }

        solution.style.height = `${solution.offsetHeight}px`;
        solution.classList.add("solution--active");

        function closeSolution() {
          solution.classList.remove("solution--active");
          closeButton.removeEventListener("click", closeSolution);
          solutionList.style = "";

          setTimeout(() => {
            solution.style = "";
          }, 300);
        }

        closeButton?.addEventListener("click", closeSolution);
      };

      // Закрываем все открытые карточки
      const activeSolutions = solutionList.querySelectorAll(
        ".solutions__card-bottom.solution--active"
      );

      if (activeSolutions.length > 0) {
        activeSolutions.forEach((solution) => {
          solution.classList.remove("solution--active");
          solutionList.style = "";

          setTimeout(() => {
            solution.style = "";
          }, 100);
        });

        // Открываем новую карточку после закрытия старых
        setTimeout(openSolution, 200);
      } else {
        openSolution();
      }
    }
  });

  function moveCardList(solutionList, solution) {
    const solutionWidth = solution.offsetWidth * 1.5;
    const solutionListWidth =
      solutionList.offsetWidth + solutionWidth - solution.offsetWidth;
    const solutionNumber = solution.dataset.num;

    solutionList.style.maxWidth = `${solutionListWidth}px`;

    switch (solutionNumber) {
      case "1":
        solutionList.style.gridTemplateColumns = `1.5fr 1fr 1fr`;
        solutionList.style.transform = `translateX(${(solutionListWidth -
          solutionList.offsetWidth) /
          2}px)`;
        break;
      case "2":
        solutionList.style.gridTemplateColumns = `1fr 1.5fr 1fr`;
        break;
      case "3":
        solutionList.style.gridTemplateColumns = `1fr 1fr 1.5fr`;
        solutionList.style.transform = `translateX(-${(solutionListWidth -
          solutionList.offsetWidth) /
          2}px)`;
        break;
      default:
        console.log("no dataset number in show-solution module");
    }
  }
}
