import { quizQuestion } from "./quizData"; // вопросы квиза

export function renderStepQuestions (quizDialog, step, questionList) {
  quizDialog.querySelector(".quiz__steps").textContent = `${step +
    1} шаг из 5`;

  // отрисовываваем заголовок
  quizDialog.querySelector(".quiz__heading").textContent =
    quizQuestion[step].title;

  // отрисовываем вопросы
  quizQuestion[step].questions.map((question, index) => {
    questionList.insertAdjacentHTML(
      "beforeend",
      `
      <li class="quiz__form-item">
        <p class="quiz__question-text">${question}</p>
        <div class="quiz__question-options">
          <label class="quiz__label">
            Да <input class="quiz__input" type="radio" name="question${index}" value="y">
            <span class="quiz__radiobutton"></span>
          </label>
          <label class="quiz__label">
            Нет <input class="quiz__input" type="radio" name="question${index}" value="n">
            <span class="quiz__radiobutton"></span>
          </label>
        </div>
      </li>
    `
    );
  });

  // отрисовывам изображение
  const stepImageContainer = quizDialog.querySelector(".quiz__info");
  // если оно существует - удаляем, потом отрисовываем новое.
  if (stepImageContainer.querySelector(".quiz__info--image")) {
    stepImageContainer.querySelector(".quiz__info--image").remove();
  }
  stepImageContainer.insertAdjacentHTML(
    "beforeend",
    `
              <img src="${quizQuestion[step].img}" alt="изображение супергероя"
          class="quiz__info--image">
    `
  );
}

