export function renderFinishScreen(quizDialog) {
    const quizContainer = quizDialog.querySelector('.quiz__container')
    quizContainer.style = "max-width: 750px"

    const finishMarkup = `
      <button class="quiz__close">
        <span class="quiz__cross"></span>
      </button>
      
      <section class="quiz__final">
        <p class="quiz__question-text text-bold">
          Сообщение успешно отправлено
        </p>
        <p class="quiz__final-text">
          Спасибо, что вы с нами! <br>
          Ваш вклад действительно имеет значение!
        </p>
        <picture>
          <source srcset="./img/superhero/services_heart.webp 1x, ./img/superhero/services_heart@2x.webp 2x" type="image/webp" />
          <source srcset="./img/superhero/services_heart.png 1x, ./img/superhero/services_heart@2x.png 2x" type="image/png" />
          <img class="quiz__final-image" src="./img/superhero/services_heart.png" alt="Изображение супергероя" />
        </picture>
        <p class="quiz__final-text">
          Скорее заберите свой подарок <br> и начните вести бизнес по-новому!
        </p>
        <a class="quiz__final-button button button--dark" href="/files/uchet.pdf" download>забрать подарок</a>
      </section>
    `
    quizContainer.textContent = ""
    quizContainer.insertAdjacentHTML('afterbegin', finishMarkup)

    const closeQuizButton = quizDialog.querySelector(".quiz__close");

    const closeQuiz = () => {
      quizDialog.classList.remove("quiz--active");
      // closeQuizButton.removeEventListener('click', closeQuiz)
    }

    closeQuizButton.addEventListener('click', closeQuiz)
  }
