import {isValidPhone} from '../../utils/isValidPhone'
import {isValidName} from '../../utils/isValidName'
import {isValidMail} from '../../utils/isValidMail'
import {isValidTextLength} from '../../utils/isValidTextLength'
import { isButtonAvailable } from './isButtonAvailable'


export const validateForm = (e) => {
    const input = e.target
    const errorMsg = input.previousElementSibling
    const label = input.closest('label')
    

    if (!errorMsg) return

    const validators = {
        name: isValidName,
        phone: isValidPhone,
        mail: isValidMail,
        work: isValidTextLength
    }

    input.id.includes(validators)

    const key = Object.keys(validators).find(type => input.id.includes(type));

    if (key) {
        const isValid = validators[key](input.value);
        errorMsg.classList.toggle('visually-hidden', isValid);
        label.classList.toggle('feedback-error', !isValid)
    }

    isButtonAvailable(e)
}