import Splide from '@splidejs/splide';
import { AutoScroll } from '@splidejs/splide-extension-auto-scroll';

const clientsSlider = document.querySelector('.clients__slider')
if(clientsSlider) {
  document.addEventListener( 'DOMContentLoaded', function() {
    console.log('clientsSlider initialized')

    const spliderOptions = {
        type: "loop",
        arrows: false,
        pagination: false,
        paginationKeyboard: true,
        paginationDirection: true,
        mediaQuery: "min",
        perPage: 1,
        // можно изменить скорость прокрутки
        autoScroll: {
            speed: 4,
        },
        breakpoints: {
          768: {
            perPage: 3,
          },
        }
      };
    var splide = new Splide( clientsSlider, spliderOptions );
    splide.mount({ AutoScroll});
  } );
}
