const menuBlocks = document.querySelectorAll(".js-accordion-menu");

if (menuBlocks.length !== 0) {

  for (let menuBlock of menuBlocks) {

    const buttons = menuBlock.querySelectorAll(
      ".finances__accordion-menu_label"
    );
    const menuItems = [
      ...menuBlock.querySelectorAll(".finances__accordion-menu_content"),
    ];

    //функция изменения менюшки
    const updateMenu = (activeButton, activeItem) => {
      buttons.forEach((button) => { button.classList.remove('finances__menu-button--active')});
      menuItems.forEach((item) => (item.style = "display: none"));
  
      activeButton.classList.add('finances__menu-button--active');
      activeItem.style = "display: block";
    };
    // по умолчанию открт первый пункт менюшки
    updateMenu(buttons[0], menuItems[0]);

    buttons.forEach((button) => {
      button.addEventListener("click", () => {
        const menuItem = menuItems.find((item) => item.id.includes(button.id));
        updateMenu(button, menuItem);
      });
    });
  }
}
