import {isValidPhone} from '../../utils/isValidPhone'
import {isValidName} from '../../utils/isValidName'
import {isValidMail} from '../../utils/isValidMail'
import {isValidTextLength} from '../../utils/isValidTextLength'

// Функция для проверки обязательных полей формы и активации кнопки

export function isFormValid(event) {
  const target = event.target;

  const quizDialog = document.querySelector(".quiz");
  const form = quizDialog.querySelector(".quiz__user-form");
  const sendFormButton = quizDialog.querySelector(".step5-button");
  const usernameInput = form.querySelector("#user-name");
  const phoneInput = form.querySelector("#user-phone");
  const emailInput = form.querySelector("#user-mail");
  const workInput = form.querySelector("#user-work");

  sendFormButton.disabled = true; // Отключаем кнопку по умолчанию

  // Функция для проверки одного поля
  function validateField(input, isValidFunc) {
    const value = input.value;
    const placeholder = input.placeholder;
    const alertMessage = input.previousElementSibling;

    if (!isValidFunc(value)) {
      alertMessage?.classList.remove("visually-hidden");

      if (input.id === "user-name" || input.id === "user-phone") {
        input.placeholder = "Это поле обязательно для заполнения";
      }
      input.classList.add("quiz__input--error");
    } else {
      alertMessage?.classList.add("visually-hidden");
      input.placeholder = placeholder;
      input.classList.remove("quiz__input--error");
    }
  }

  function validateForm() {
    const isNameValid = isValidName(usernameInput.value);
    const isPhoneValid = isValidPhone(phoneInput.value);
    const isMailValid = isValidMail(emailInput.value);
    const isTextareaValid = isValidTextLength(workInput.value);

    // Активируем кнопку, если поля валидны
    return !(isNameValid && isPhoneValid && isMailValid && isTextareaValid);
  }

  if (target === usernameInput) {
    validateField(usernameInput, isValidName);
  }

  if (target === phoneInput) {
    validateField(phoneInput, isValidPhone);
  }

  if (target === emailInput) {
    validateField(emailInput, isValidMail);
  }

  if (target === workInput) {
    validateField(workInput, isValidTextLength);
  }

  // Проверяем всю форму после изменения любого поля
  sendFormButton.disabled = validateForm();
}
