const topArrowButton = document.getElementById('topArrow')

if (topArrowButton) {

    const usersScreenHeight = window.innerHeight / 2;

    window.addEventListener( 'scroll', () => {

        window.scrollY > usersScreenHeight
            ? topArrowButton.classList.add('is-top-button-active')
            : topArrowButton.classList.remove('is-top-button-active')

        
        topArrowButton.classList.contains('is-top-button-active') 
        && topArrowButton.addEventListener( 'click', () => {

            window.scrollTo( {
                top: 0,
            } )

        })
        
    })
}
