let isHandlerActive = false; // Флаг, указывающий, активен ли обработчик

const activateCasesSlider = () => {
  const caseItems = document.querySelectorAll(".case__card");
  const caseNavlist = document.querySelector(".case__nav");
  const caseNavButtons = caseNavlist.querySelectorAll(".case__nav-button");

  const caseMap = {
    trouble: 0,
    solution: 1,
    result: 2,
  };

  const hideAllCases = () =>
    caseItems.forEach((el) => el.classList.add("visually-hidden"));
  const showCase = (index) => {
    if (caseItems[index]) {
      caseItems[index].classList.remove("visually-hidden");
    }
  };

  // Подсвечиваем первую кнопку по умолчанию
  const activateDefaultButton = () => {
    if (caseNavButtons.length > 0) {
      caseNavButtons.forEach((button) =>
        button.classList.remove("button--dark")
      );
      caseNavButtons[0].classList.add("button--dark"); // Подсвечиваем первую кнопку
    }
  };

  // Показываем первый элемент по умолчанию
  hideAllCases();
  showCase(caseMap["trouble"]);

  // Подсвечиваем первую кнопку
  activateDefaultButton();

  const handleNavClick = (evt) => {
    const target = evt.target.closest(".case__nav-button");
    if (!target) return;

    const elementAttr = target.dataset.value;

    caseNavButtons.forEach((button) => button.classList.remove("button--dark"));
    target.classList.add("button--dark");

    hideAllCases();
    showCase(caseMap[elementAttr] || caseMap["trouble"]);
  };

  // Добавляем обработчик кликов
  caseNavlist.addEventListener("click", handleNavClick);

  // Возвращаем функцию для удаления обработчика
  return () => {
    caseNavlist.removeEventListener("click", handleNavClick);

    // Удаляем класс visually-hidden у всех элементов
    caseItems.forEach((el) => el.classList.remove("visually-hidden"));
  };
};

// Инициализация и управление в зависимости от разрешения экрана
let removeClickHandler;

const updateHandler = () => {
  if (window.innerWidth <= 768) {
    if (!isHandlerActive) {
      isHandlerActive = true;
      removeClickHandler = activateCasesSlider();
    }
  } else {
    if (isHandlerActive) {
      isHandlerActive = false;
      if (removeClickHandler) {
        removeClickHandler();
        removeClickHandler = null;
      }
    }
  }
};


// проверям что находимся на странице кейсов 
const pageURL = window.location.href

if( pageURL.includes('case') ) {

  document.addEventListener("DOMContentLoaded", updateHandler);
window.addEventListener("resize", updateHandler);



// Начальная проверка при загрузке
updateHandler();

}


