import {validateForm} from "./validateForm";

const formBlock = document.getElementById("feedback-form-block");
const form = formBlock?.querySelector(".feedback-form");
const firstScreen = formBlock?.querySelector(".feedback__first-screen");
const secondScreen = formBlock?.querySelector(".feedback__second-screen");
const thirdScreen = formBlock?.querySelector(".feedback__third-screen");


function toggleFormVisibility(e) {


  const elem = e.target;

  if (
    elem.classList.contains("js-feedback-popup")
    || elem.parentElement.classList.contains("js-feedback-popup")
  ) {
    e.preventDefault();
    formBlock.classList.add("feedback-active");
  } else if (elem.classList.contains("feedback__goContacts")) {
    e.preventDefault()
    formBlock.classList.remove("feedback-active");
    location.hash = '#contacts'

  } else if (
    elem.classList.contains("feedback-form__close") ||
    elem.classList.contains("feedback-form__wrapper")

  ) {
    formBlock.classList.remove("feedback-active");
  }
}

function onFormSend(e) {
  e.preventDefault();
  // здесь логика по отправке формы, если она нужна.
  //console.log('здесь должна быть логика по отправке формы:  src/js/blocks/feedbackForm.js в функции onFormSend')

  let data = {
    contacts: {},
  };
  data.contacts = {
    "user-name": document.querySelector("#feedback-name").value,
    "user-phone": document.querySelector("#feedback-phone").value,
    "user-mail": document.querySelector("#feedback-mail").value,
    "user-info": document.querySelector("#feedback-work").value,
  };
  fetch("/php/mail.php", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  })
    // .then((response) => response.json())
    .then(() => {
      //скрываем форму, показываем сообщение об отправке
      firstScreen.classList.add("visually-hidden");
      secondScreen.classList.remove("visually-hidden");
    })
    .catch((error) => {
      console.warn("Ошибка:", error);
      firstScreen.classList.add("visually-hidden");
      thirdScreen.classList.remove("visually-hidden");
    });

}

function initialFeedbackForm() {
  if (formBlock) {

    // если была ошибка отправки данный, то скрываем блок с ней при инициализации, и показываем форму
    if (!thirdScreen.classList.contains('visually-hidden')) {
      thirdScreen.classList.add('visually-hidden')
      firstScreen.classList.remove('visually-hidden')
    }


    formBlock.addEventListener("change", validateForm);
  }
  document.addEventListener("click", toggleFormVisibility);

  if (form) form.addEventListener("submit", onFormSend);
}

initialFeedbackForm();
