const notfound = document.querySelector(".notfound");

if (notfound) {
  const firstScreen = notfound.querySelector(".notfound__first-screen");

    if (window.innerWidth > 768) {
      const secondScreen = notfound.querySelector(".notfound__second-screen");
  
      const showAnimation = () => {
        firstScreen.classList.add("notfound__section--close");
        secondScreen.classList.remove("notfound__section--close");
      };
  
      setTimeout(showAnimation, 3000);
    } else {
      const secondScreenBlock = notfound.querySelector('.notfound__second-screen');
      const secondScreen = notfound.querySelector(".notfound__picture-container");
      const thirdScreen = notfound.querySelector(".notfound__info");
  
  
      secondScreen.classList.add("notfound__section--close");
      thirdScreen.classList.add("notfound__section--close");
  
      const showSecondScreen = () => {
        secondScreenBlock.classList.remove('notfound__section--close')
        firstScreen.classList.add("notfound__section--close");
        secondScreen.classList.remove("notfound__section--close");
      };
  
      const showThirdScreen = () => {
        secondScreen.classList.add("notfound__section--close");
        thirdScreen.classList.remove("notfound__section--close");
      };
  
      setTimeout(showSecondScreen, 3000)
      setTimeout(showThirdScreen, 5000)
    }

}
