import Splide from '@splidejs/splide';
import { AutoScroll } from '@splidejs/splide-extension-auto-scroll';

const solutionsSlider = document.getElementById('solutionsSlider')



if(solutionsSlider) {

  document.addEventListener( 'DOMContentLoaded', function() {
    


    const spliderOptions = {
        type: "loop",
        arrows: true,
        pagination: true,
        paginationKeyboard: true,
        paginationDirection: true,
        mediaQuery: "min",
        perPage: 1,

        // можно изменить скорость прокрутки
        autoScroll: { 
            speed: 0,
        },
      };
    var splide = new Splide( solutionsSlider, spliderOptions );
    splide.mount();
  } );
}
  