const header = document.querySelector(".header");

if (header) {

  let ticking = false;
  const topHeaderHeight = header.offsetHeight;

  // рассчитывает значение высоты не липкого хедера, чтобы при изменении стиля, документу добавить выосту изъятого блока

  window.addEventListener("scroll", () => {
    const scrollY = window.scrollY;
    const screenWidth = window.innerWidth;

    if (!ticking) {
      window.requestAnimationFrame(() => {
        if (scrollY > 1000 && screenWidth > 768) {
          header.classList.add("hide");
        } else {
          header.classList.remove("hide");
        }

        if (scrollY > 1500 && screenWidth > 768) {
          document.body.style.marginTop = `${topHeaderHeight}px`;
          header.classList.add("fixed");
        } else {
          document.body.style.marginTop = "0";
          header.classList.remove("fixed");
        }

        ticking = false;
      });

      ticking = true;
    }
  });
}
