import { isFormValid } from "./quizValidation"; // валидация полей формы
import { renderQuizForm, renderStepQuestions } from "./quizRenderFunctions";
import { renderFinishScreen } from "./quizRenderFunctions";
import { quizQuestion } from "./quizData";

const quizDialog = document.querySelector(".quiz");

if (quizDialog) {
  // флаг начального шага квиза
  let step = 0;

  let answersData = {
    answers: {},
    contacts: {},
  };
  function writeQuizData(form) {
    if (form.classList.contains("quiz__form")) {
      //-------------------------------- секция для записи информации в блок ответов

      // Находим все элементы с вопросами внутри формы
      const questionItems = form.querySelectorAll(".quiz__form-item");

      questionItems.forEach((item) => {
        // Извлекаем текст вопроса
        const questionTextElem = item.querySelector(".quiz__question-text");
        const questionText = questionTextElem
          ? questionTextElem.textContent.trim()
          : "";

        const radios = item.querySelectorAll('input[type="radio"]');
        if (radios.length === 0) return;

        // Получаем имя группы радиокнопок
        const fieldName = radios[0].name;

        // Проверяем, какая радиокнопка выбрана
        const selectedRadio = Array.from(radios).find((radio) => radio.checked);
        const answer = selectedRadio ? selectedRadio.value : null;

        if (!answersData.answers[`form${step + 1}`]) {
          answersData.answers[`form${step + 1}`] = [];
        }

        answersData.answers[`form${step + 1}`].push({
          field: fieldName,
          text: questionText,
          value: answer,
        });
      });
    } else if (form.classList.contains("quiz__user-form")) {
      const userInfo = Object.fromEntries(new FormData(form).entries());
      answersData.contacts = userInfo;
    }
  }
  function sendData() {
    fetch("/php/mail.php", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(answersData),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("Успех:", data);
      })
      .catch((error) => {
        console.warn("Ошибка:", error);
      });
  }
  function checkWrongAnswers() {
    let result = {
      true: 0,
      false: 0,
    };
    for (let key in answersData.answers) {
      const formAnswers = answersData.answers[key];
      formAnswers.forEach((obj) =>
        obj.value === "y"
          ? (result.true = result.true + 1)
          : (result.false = result.false + 1)
      );
    }
    return result;
  }
  function scrollToTop () {
    document.querySelector('.quiz__container')
    .scrollIntoView({ behavior: "smooth" })
  }
  function renderQuestions() {
    // ------------------- Отрисовка вопросов на конкретном шаге-------------------
    const questionList = quizDialog.querySelector(".quiz__form-list");
    renderStepQuestions(quizDialog, step, questionList);

    // ------------------- Активация кнопки следующего шага -------------------
    const nextButton = quizDialog.querySelector(".quiz__next--button");
    const nextBlockAlertMsg = nextButton.nextElementSibling;

    nextButton.disabled = true;
    const form = quizDialog.querySelector(".quiz__form");
    // функция проверяет, если все радиокнопки выбраны
    function isNextButtonActive() {
      const formData = new FormData(form);
      const data = [];
      const questionsCount = quizDialog.querySelectorAll(".quiz__form-item")
        .length;

      formData.forEach((value) => {
        data.push(value);
      });

      if (data.length === questionsCount) {
        nextButton.disabled = false;
        nextBlockAlertMsg.classList.add("visually-hidden");
      } else {
        nextButton.disabled = true;
        nextBlockAlertMsg.classList.remove("visually-hidden");
      }
    }
    form.addEventListener("change", isNextButtonActive);

    // ------------------- Переход по шагам  -------------------
    function nextStep() {
      writeQuizData(form);

      step = step + 1;

      if (step < 4) {
        questionList.textContent = "";
        form.removeEventListener("change", isNextButtonActive);
        nextButton.removeEventListener("click", nextStep);

        renderQuestions();
        scrollToTop()
      } else {
        quizDialog.querySelector(".quiz__steps").textContent = `${step +
          1} шаг из 5`;

        const results = checkWrongAnswers();

        renderQuizForm(quizDialog, results);

        const userForm = quizDialog.querySelector(".quiz__user-form");
        const sendFormButton = quizDialog.querySelector(".step5-button");
        sendFormButton.disabled = true; // Отключаем кнопку по умолчанию

        // Слушаем изменения каждого поля
        userForm.addEventListener("change", isFormValid);

        //при нажатии кнопки  - отрисовываем последнее окно, ссылку на скачивание файла.
        sendFormButton.addEventListener("click", () => {
          writeQuizData(userForm);
          sendData()
          renderFinishScreen(quizDialog);
        });
      }
    }
    nextButton.addEventListener("click", nextStep);
  }

  // hide & show quiz modal
  const showQuizButton = document.querySelector(".services__promo-button");
  const closeQuizButton = document.querySelector(".quiz__close");


  showQuizButton?.addEventListener("click", (evt) => {
    evt.preventDefault();
    quizDialog.classList.add("quiz--active");
    if (step === quizQuestion.length + 1) {
      renderFinishScreen(quizDialog);
    }
  });
  closeQuizButton.addEventListener("click", () => {
    quizDialog.classList.remove("quiz--active");
  });

  document.addEventListener('DOMContentLoaded', () => {
    const startUrl = "http://localhost:8000/services.html#quiz-start" 
    if(window.location.href === startUrl) {
      quizDialog.classList.add("quiz--active");
      if (step === quizQuestion.length + 1) {
        renderFinishScreen(quizDialog);
      }
      renderQuestions();
    } else {
      renderQuestions();
    }
  })
}
