const accordions = document.querySelectorAll(".finances-control__accordion");

if (accordions) {
  function toggleAccordion(e) {
    accordions.forEach((accordion) => {
      if (accordion !== e.currentTarget) {
        accordion.classList.remove("accordion--open");
      }
    });

    if (e.target.classList.value === "finances-control__accordion-title") {
      const accordion = e.currentTarget;
      accordion.scrollIntoView()
      if(accordion.classList.contains("accordion--open")) {
        // скроллит страничку к верхнему блоку аккордеона
        accordion.scrollIntoView()
      }

      accordion.classList.toggle("accordion--open");
    }
  }

  accordions.forEach((accordion) =>
    accordion.addEventListener("click", toggleAccordion)
  );
}
